script:
var SAMPLE_INDEX = {{sample}};
var SPEED = {{speed}};

var linksGroup = document.getElementById('links');
var nodesGroup = document.getElementById('tree-nodes');
var caption = document.getElementById('caption');
var sampleChip = document.getElementById('sample-label');

// 四个待判断的样本：是否下雨 / 空气质量是否良好 / 是否感冒
var SAMPLES = [
  { rain: true, air: false, cold: false },
  { rain: false, air: true, cold: false },
  { rain: false, air: true, cold: true },
  { rain: false, air: false, cold: true }
];

// 一棵固定的三问小树（判断「今天适不适合户外跑步」）
// ★★ 坐标必须落在 viewBox（460 × 268）以内，**含矩形自身的一半高度** ——
//    节点矩形是后画的，会盖住落进它里面的字，所以每层还要给「是 / 否」标签
//    留出约 33 单位（标签画在两层正中偏上）。四层的纵向预算：
//    根 32±16 → 104±16 → 170±16 → 236±15，最下面再留一次放大动画（1.06）的余量。
var ROOT = {
  x: 210,
  y: 32,
  title: '下雨？',
  yes: { x: 76, y: 104, title: '不适合', leaf: true },
  no: {
    x: 310,
    y: 104,
    title: '空气好？',
    yes: {
      x: 232,
      y: 170,
      title: '感冒？',
      yes: { x: 150, y: 236, title: '不适合', leaf: true },
      no: { x: 314, y: 236, title: '适合', leaf: true }
    },
    no: { x: 384, y: 170, title: '不适合', leaf: true }
  }
};

var drawn = [];
var links = [];

function drawNode(node, parent, branchLabel) {
  if (parent) {
    var line = Sandbox.svgEl('line');
    line.setAttribute('x1', String(parent.x));
    line.setAttribute('y1', String(parent.y));
    line.setAttribute('x2', String(node.x));
    line.setAttribute('y2', String(node.y));
    line.setAttribute('stroke', '#d6ddec');
    line.setAttribute('stroke-width', '1.6');
    linksGroup.appendChild(line);

    var text = Sandbox.svgEl('text');
    text.setAttribute('x', String((parent.x + node.x) / 2));
    text.setAttribute('y', String((parent.y + node.y) / 2 - 4));
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('class', 'axis-label');
    text.textContent = branchLabel;
    linksGroup.appendChild(text);
    links.push({ line: line, to: node });
  }

  var rect = Sandbox.svgEl('rect');
  var w = node.leaf ? 74 : 86;
  var h = node.leaf ? 30 : 32;
  rect.setAttribute('x', String(node.x - w / 2));
  rect.setAttribute('y', String(node.y - h / 2));
  rect.setAttribute('width', String(w));
  rect.setAttribute('height', String(h));
  rect.setAttribute('rx', node.leaf ? '15' : '7');
  rect.setAttribute('fill', node.leaf ? '#eef2f8' : '#ffffff');
  rect.setAttribute('stroke', '#2f6fd0');
  rect.setAttribute('stroke-width', '1.5');
  nodesGroup.appendChild(rect);

  var label = Sandbox.svgEl('text');
  label.setAttribute('x', String(node.x));
  label.setAttribute('y', String(node.y + 4));
  label.setAttribute('text-anchor', 'middle');
  label.setAttribute('class', 'axis-label');
  label.setAttribute('style', 'font-size:12px;' + (node.leaf ? 'fill:#1f9d63;font-weight:600' : 'fill:#12233b'));
  label.textContent = node.title;
  nodesGroup.appendChild(label);

  node.rect = rect;
  node.label = label;
  drawn.push(node);

  if (node.yes) drawNode(node.yes, node, '是');
  if (node.no) drawNode(node.no, node, '否');
}

drawNode(ROOT, null, '');

var sample = SAMPLES[SAMPLE_INDEX] || SAMPLES[0];
sampleChip.textContent =
  '样本：' + (sample.rain ? '下雨' : '不下雨') + ' / ' + (sample.air ? '空气好' : '空气差') + ' / ' + (sample.cold ? '感冒' : '没感冒');

function branchFor(question, sampleData) {
  if (question === '下雨？') return sampleData.rain ? 'yes' : 'no';
  if (question === '空气好？') return sampleData.air ? 'yes' : 'no';
  return sampleData.cold ? 'yes' : 'no';
}

Sandbox.play(function () {
  var steps = [];
  var path = [];
  var node = ROOT;
  while (node && !node.leaf) {
    path.push(node);
    node = node[branchFor(node.title, sample)];
  }
  var leaf = node;

  function focus(target) {
    return {
      targets: target.rect,
      scale: [1, 1.06],
      duration: 260 * SPEED,
      direction: 'alternate',
      begin: function () {
        caption.textContent = target.leaf
          ? '叶子节点给出的就是预测结果：' + target.title + '。'
          : '当前节点问：' + target.title + ' —— 按样本回答走分支。';
      }
    };
  }

  for (var i = 0; i < path.length; i += 1) {
    var current = path[i];
    var next = current[branchFor(current.title, sample)];
    steps.push(focus(current));
    steps.push({
      targets: (function () {
        var matched = [];
        for (var k = 0; k < links.length; k += 1) if (links[k].to === next) matched.push(links[k].line);
        return matched;
      })(),
      stroke: '#2f6fd0',
      strokeWidth: 3,
      duration: 260 * SPEED
    });
  }
  if (leaf) steps.push(focus(leaf));
  steps.push({
    targets: leaf ? leaf.rect : ROOT.rect,
    fill: '#dff5e9',
    stroke: '#1f9d63',
    duration: 300 * SPEED,
    complete: function () {
      caption.textContent = '结论：' + (leaf ? leaf.title : '') + '。整条路径就是一次「用树做判断」的过程。';
    }
  });

  var timeline = anime.timeline({ autoplay: true, easing: 'easeInOutQuad' });
  for (var s = 0; s < steps.length; s += 1) timeline.add(steps[s]);
  timeline.play();

  var total = timeline.duration || 5000;
  return {
    pause: function () { timeline.pause(); },
    play: function () { timeline.play(); },
    restart: function () { timeline.restart(); },
    finished: {
      then: function (resolve) {
        var elapsed = 0;
        var timer = setInterval(function () {
          elapsed += 100;
          if (timeline.completed || elapsed > total + 800) {
            clearInterval(timer);
            resolve();
          }
          Sandbox.progress(Math.min(1, elapsed / total));
        }, 100);
      }
    }
  };
});

Sandbox.ready({ template: 'decision-tree', sample: SAMPLE_INDEX });
